import { useCallback, useEffect, useRef, useState } from 'react';
import { Game } from './game/engine';
import { Input } from './game/input';
import { audio } from './game/audio';
import { loadSave, upgradeCost, writeSave, MAX_LVL } from './game/types';
import type { EndStats, HudState, Save, Toast, UpgradeId, ZoneId } from './game/types';
import { Menu } from './components/Menu';
import { Hud } from './components/Hud';
import { GameOver, PauseMenu } from './components/Overlays';
import { TouchControls } from './components/TouchControls';

type Screen = 'menu' | 'play' | 'pause' | 'over';

const STYLE = `
.mt-font { font-family: 'Arial Black', 'Impact', system-ui, sans-serif; letter-spacing: .02em }
.mt-title { background: linear-gradient(180deg, #fff7c2 0%, #ffd23c 40%, #ff6a1c 75%, #d6281c 100%); -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 4px 0 #3a0d10) drop-shadow(0 0 24px rgba(255,120,40,.55)); }
@keyframes mt-pop { 0% { transform: translateY(10px) scale(.6); opacity: 0 } 15% { transform: translateY(0) scale(1.12); opacity: 1 } 25% { transform: scale(1) } 80% { opacity: 1 } 100% { transform: translateY(-24px); opacity: 0 } }
.mt-pop { animation: mt-pop 1.8s ease-out both }
@keyframes mt-blink { 50% { opacity: .25 } }
.mt-blink { animation: mt-blink .6s steps(1) infinite }
@keyframes mt-float { 50% { transform: translateY(-6px) } }
.mt-float { animation: mt-float 2.4s ease-in-out infinite }
`;

export default function App() {
  const wrapRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameRef = useRef<Game | null>(null);
  const [input, setInput] = useState<Input | null>(null);
  const [screen, setScreen] = useState<Screen>('menu');
  const [hud, setHud] = useState<HudState | null>(null);
  const [end, setEnd] = useState<EndStats | null>(null);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [zone, setZone] = useState<ZoneId>('desierto');
  const [save, setSave] = useState<Save>(() => loadSave());
  const [muted, setMuted] = useState(false);

  useEffect(() => {
    const inp = new Input();
    inp.attach();
    setInput(inp);
    const g = new Game(canvasRef.current!, inp, {
      onHud: setHud,
      onEnd: s => { setEnd(s); setSave(loadSave()); window.setTimeout(() => setScreen('over'), 400); },
      onToast: t => {
        setToasts(list => [...list.slice(-3), t]);
        window.setTimeout(() => setToasts(list => list.filter(x => x.id !== t.id)), 1800);
      },
    });
    gameRef.current = g;
    const wrap = wrapRef.current!;
    const fit = () => { const r = wrap.getBoundingClientRect(); g.resize(r.width, r.height); };
    const ro = new ResizeObserver(fit);
    ro.observe(wrap);
    fit();
    g.run();
    return () => { ro.disconnect(); g.destroy(); inp.detach(); audio.dispose(); gameRef.current = null; };
  }, []);

  const pickZone = useCallback((z: ZoneId) => {
    setZone(z);
    gameRef.current?.setAttractZone(z);
  }, []);

  const play = useCallback(() => {
    (document.activeElement as HTMLElement | null)?.blur?.();
    audio.init();
    audio.startMusic();
    gameRef.current?.start(zone);
    setEnd(null);
    setToasts([]);
    setScreen('play');
  }, [zone]);

  const setPaused = useCallback((v: boolean) => {
    if (gameRef.current) gameRef.current.paused = v;
    setScreen(v ? 'pause' : 'play');
  }, []);

  const toMenu = useCallback(() => {
    gameRef.current?.toAttract();
    audio.stopMusic();
    setSave(loadSave());
    setHud(null);
    setScreen('menu');
  }, []);

  const buy = useCallback((id: UpgradeId) => {
    setSave(prev => {
      const lvl = prev.up[id];
      const cost = upgradeCost(lvl);
      if (lvl >= MAX_LVL || prev.coins < cost) return prev;
      const next: Save = { ...prev, coins: prev.coins - cost, up: { ...prev.up, [id]: lvl + 1 } };
      writeSave(next);
      audio.init();
      audio.fuel();
      return next;
    });
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.code === 'Escape' || e.code === 'KeyP') { if (screen === 'play' || screen === 'pause') setPaused(screen === 'play'); }
      else if (e.code === 'Enter' && (screen === 'menu' || screen === 'over')) play();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [screen, play, setPaused]);

  const toggleMute = () => { setMuted(!muted); audio.setMuted(!muted); };

  return (
    <div ref={wrapRef} className="relative h-[100dvh] w-full select-none overflow-hidden bg-[#1d0b3a] text-white">
      <style>{STYLE}</style>
      <canvas ref={canvasRef} className="absolute inset-0 block h-full w-full" />
      {screen === 'menu' && (
        <Menu zone={zone} setZone={pickZone} save={save} onBuy={buy} muted={muted} onMute={toggleMute} onPlay={play} />
      )}
      {(screen === 'play' || screen === 'pause') && hud && (
        <Hud h={hud} toasts={toasts} muted={muted} onMute={toggleMute} onPause={() => setPaused(true)} />
      )}
      {screen === 'play' && <TouchControls input={input} />}
      {screen === 'pause' && <PauseMenu onResume={() => setPaused(false)} onRestart={play} onMenu={toMenu} />}
      {screen === 'over' && end && <GameOver stats={end} onRetry={play} onMenu={toMenu} />}
    </div>
  );
}

import clsx from 'clsx';
import { Coins, Flag, Fuel, Magnet, Pause, Trophy, Volume2, VolumeX, Zap } from 'lucide-react';
import type { HudState, Toast } from '../game/types';

interface Props { h: HudState; toasts: Toast[]; muted: boolean; onMute: () => void; onPause: () => void }

const SH = { textShadow: '0 2px 0 rgba(0,0,0,.6)' };

function Speedo({ v }: { v: number }) {
  const max = 160;
  const k = Math.min(1, v / max);
  const a0 = Math.PI * 0.8, a1 = Math.PI * 2.2;
  const arc = (from: number, to: number) => {
    const r = 44, cx = 56, cy = 56;
    const p = (a: number) => `${cx + Math.cos(a) * r} ${cy + Math.sin(a) * r}`;
    return `M ${p(from)} A ${r} ${r} 0 ${to - from > Math.PI ? 1 : 0} 1 ${p(to)}`;
  };
  const na = a0 + (a1 - a0) * k;
  return (
    <svg width="112" height="100" viewBox="0 0 112 100" className="drop-shadow-lg">
      <circle cx="56" cy="56" r="52" fill="rgba(10,6,20,.55)" />
      <path d={arc(a0, a1)} stroke="rgba(255,255,255,.15)" strokeWidth="8" fill="none" strokeLinecap="round" />
      {k > 0.01 && <path d={arc(a0, a0 + (a1 - a0) * k)} stroke="url(#mtg)" strokeWidth="8" fill="none" strokeLinecap="round" />}
      <defs><linearGradient id="mtg" x1="0" x2="1"><stop offset="0" stopColor="#ffd23c" /><stop offset="1" stopColor="#ff3d2e" /></linearGradient></defs>
      <line x1="56" y1="56" x2={56 + Math.cos(na) * 36} y2={56 + Math.sin(na) * 36} stroke="#fff" strokeWidth="3" strokeLinecap="round" />
      <circle cx="56" cy="56" r="5" fill="#ff4a1c" />
      <text x="56" y="84" textAnchor="middle" fill="#fff" fontSize="18" fontWeight="900" fontFamily="Arial Black, sans-serif">{v}</text>
      <text x="56" y="96" textAnchor="middle" fill="rgba(255,255,255,.6)" fontSize="8" fontWeight="700">KM/H</text>
    </svg>
  );
}

export function Hud({ h, toasts, muted, onMute, onPause }: Props) {
  const low = h.fuel < 0.2;
  const toRecord = h.best > 0 ? Math.min(1, h.dist / h.best) : 0;
  return (
    <div className="pointer-events-none absolute inset-0 text-white" style={SH}>
      <div className="flex items-start justify-between gap-3 p-3 md:p-4">
        <div>
          <div className="mt-font text-4xl italic leading-none md:text-5xl">{h.dist}<span className="text-xl text-orange-200"> m</span></div>
          <div className="mt-1 flex items-center gap-2 text-[11px] font-bold text-emerald-200">
            <Trophy size={12} /> Récord {h.best} m
            <div className="h-1.5 w-20 overflow-hidden rounded-full bg-white/15">
              <div className="h-full bg-emerald-300" style={{ width: `${toRecord * 100}%` }} />
            </div>
          </div>
          <div className="mt-1 flex items-center gap-1 text-[11px] text-yellow-200/90"><Flag size={12} /> Meta parcial: {h.next} m · {h.zone}</div>
        </div>

        <div className="flex flex-col items-center">
          <div className={clsx('flex items-center gap-2 rounded-full border bg-black/45 px-3 py-1.5', low ? 'border-red-400 mt-blink' : 'border-white/15')}>
            <Fuel size={18} className={low ? 'text-red-400' : 'text-orange-300'} />
            <div className="h-3 w-32 overflow-hidden rounded-full bg-white/10 md:w-48">
              <div
                className="h-full rounded-full transition-[width] duration-200"
                style={{ width: `${h.fuel * 100}%`, background: low ? '#ff3b3b' : 'linear-gradient(90deg,#ff3d2e,#ffb02e,#ffe45c)' }}
              />
            </div>
          </div>
          {low && <div className="mt-1 text-[11px] font-black tracking-widest text-red-300">¡POCO COMBUSTIBLE!</div>}
        </div>

        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1.5 rounded-full bg-black/45 px-3 py-1.5 text-lg font-black text-yellow-300">
            <Coins size={18} /> {h.coins}
          </div>
          <button onClick={onMute} className="pointer-events-auto rounded-full bg-black/45 p-2 hover:bg-black/65" aria-label="Silenciar">
            {muted ? <VolumeX size={18} /> : <Volume2 size={18} />}
          </button>
          <button onClick={onPause} className="pointer-events-auto rounded-full bg-black/45 p-2 hover:bg-black/65" aria-label="Pausa">
            <Pause size={18} />
          </button>
        </div>
      </div>

      <div className="absolute left-1/2 top-24 flex -translate-x-1/2 flex-col items-center gap-1">
        {toasts.map(t => (
          <div key={t.id} className="mt-pop text-center">
            <div className="mt-font text-3xl italic md:text-4xl" style={{ color: t.color, textShadow: '0 3px 0 rgba(0,0,0,.55), 0 0 18px ' + t.color + '88' }}>{t.text}</div>
            {t.sub && <div className="text-xs font-bold text-white/85">{t.sub}</div>}
          </div>
        ))}
      </div>

      <div className="absolute bottom-3 left-3 flex items-end gap-3 md:bottom-4 md:left-4">
        <div className="flex items-center gap-1 rounded-2xl bg-black/45 px-3 py-2">
          {[0, 1, 2].map(i => (
            <Zap key={i} size={20} className={i < h.nitro ? 'text-sky-300' : 'text-white/15'} fill={i < h.nitro ? 'currentColor' : 'none'} />
          ))}
          <span className={clsx('ml-1 text-[10px] font-black tracking-widest', h.nitroOn ? 'text-sky-200 mt-blink' : 'text-white/60')}>
            {h.nitroOn ? 'NITRO' : 'ESPACIO'}
          </span>
        </div>
        {h.magnet > 0 && (
          <div className="flex items-center gap-1 rounded-2xl bg-red-500/30 px-3 py-2 text-xs font-black">
            <Magnet size={16} /> {Math.ceil(h.magnet)} s
          </div>
        )}
        {h.air && <div className="mt-font rounded-2xl bg-fuchsia-500/30 px-3 py-1.5 text-sm italic">¡EN EL AIRE!</div>}
      </div>

      <div className="absolute bottom-24 right-3 md:bottom-3 md:right-4">
        <Speedo v={h.speed} />
      </div>
    </div>
  );
}

import clsx from 'clsx';
import { Coins, Cog, Fuel, Gauge, Mountain, Moon, Play, Snowflake, Star, Sun, Trophy, Volume2, VolumeX, Wrench } from 'lucide-react';
import type { ReactNode } from 'react';
import { MAX_LVL, UPGRADES, upgradeCost, ZONES } from '../game/types';
import type { Save, UpgradeId, ZoneId } from '../game/types';

interface Props {
  zone: ZoneId; setZone: (z: ZoneId) => void; save: Save; onBuy: (id: UpgradeId) => void;
  muted: boolean; onMute: () => void; onPlay: () => void;
}

const ZONE_ICON: Record<ZoneId, ReactNode> = { desierto: <Sun size={18} />, nieve: <Snowflake size={18} />, luna: <Moon size={18} /> };
const UP_ICON: Record<UpgradeId, ReactNode> = { engine: <Cog size={18} />, suspension: <Mountain size={18} />, tires: <Gauge size={18} />, tank: <Fuel size={18} /> };
const ZONE_TINT: Record<ZoneId, string> = {
  desierto: 'from-orange-500/30 to-fuchsia-700/30 border-orange-300/60',
  nieve: 'from-sky-400/30 to-indigo-700/30 border-sky-200/60',
  luna: 'from-slate-400/25 to-slate-900/40 border-slate-200/60',
};

export function Menu({ zone, setZone, save, onBuy, muted, onMute, onPlay }: Props) {
  return (
    <div className="absolute inset-0 overflow-y-auto bg-gradient-to-r from-black/75 via-black/35 to-black/60">
      <button onClick={onMute} className="absolute right-4 top-4 z-10 rounded-full border border-white/20 bg-black/40 p-2 hover:bg-black/60" aria-label="Silenciar">
        {muted ? <VolumeX size={18} /> : <Volume2 size={18} />}
      </button>
      <div className="mx-auto flex min-h-full max-w-6xl flex-col gap-6 p-5 md:flex-row md:items-center md:gap-10 md:p-10">
        <div className="flex-1">
          <div className="text-xs font-bold uppercase tracking-[0.4em] text-orange-200/80">NONA · Colinas extremas</div>
          <h1 className="mt-font mt-title mt-float mt-1 text-6xl italic leading-[0.9] md:text-8xl">MONSTER<br />TRUCK</h1>
          <p className="mt-4 max-w-md text-sm text-white/80 md:text-base">
            Domina la suspensión, vuela sobre las rampas y haz mortales. Recoge combustible antes de quedarte seco y gasta tus monedas en el garaje.
          </p>

          <div className="mt-5 text-[11px] font-bold uppercase tracking-widest text-white/60">Zona</div>
          <div className="mt-2 grid grid-cols-3 gap-2">
            {ZONES.map(z => (
              <button
                key={z.id}
                onClick={() => setZone(z.id)}
                className={clsx(
                  'rounded-xl border bg-gradient-to-br p-2.5 text-left transition hover:scale-[1.03]',
                  ZONE_TINT[z.id],
                  zone === z.id ? 'ring-2 ring-yellow-300 shadow-[0_0_24px_rgba(255,200,60,.35)]' : 'opacity-75',
                )}
              >
                <div className="flex items-center gap-1.5 text-sm font-black">{ZONE_ICON[z.id]} <span className="truncate">{z.name}</span></div>
                <div className="mt-1 flex gap-0.5 text-yellow-300">
                  {[1, 2, 3].map(i => <Star key={i} size={11} fill={i <= z.stars ? 'currentColor' : 'none'} />)}
                </div>
                <div className="mt-1 hidden text-[11px] leading-tight text-white/70 sm:block">{z.desc}</div>
                <div className="mt-1.5 flex items-center gap-1 text-[11px] text-emerald-200"><Trophy size={11} /> {save.best[z.id]} m</div>
              </button>
            ))}
          </div>

          <button
            onClick={onPlay}
            className="mt-font mt-6 flex w-full max-w-sm items-center justify-center gap-3 rounded-2xl border-b-[6px] border-red-900 bg-gradient-to-b from-yellow-300 via-orange-500 to-red-600 px-8 py-4 text-2xl text-white shadow-[0_10px_40px_rgba(255,90,30,.5)] transition hover:scale-105 active:translate-y-1 active:border-b-2"
            style={{ textShadow: '0 3px 0 #7a1608' }}
          >
            <Play size={26} fill="currentColor" /> Jugar
          </button>
          <div className="mt-4 grid max-w-md grid-cols-2 gap-x-4 gap-y-1 text-[12px] text-white/70">
            <span><b className="text-white">→ / W</b> acelerar · inclinar atrás</span>
            <span><b className="text-white">← / S</b> frenar · inclinar adelante</span>
            <span><b className="text-white">Espacio</b> nitro</span>
            <span><b className="text-white">P / Esc</b> pausa · <b className="text-white">Enter</b> jugar</span>
          </div>
        </div>

        <div className="w-full rounded-3xl border border-white/15 bg-black/55 p-5 shadow-2xl backdrop-blur-md md:w-[400px]">
          <div className="flex items-center justify-between">
            <div className="mt-font flex items-center gap-2 text-xl"><Wrench size={20} className="text-orange-300" /> Garaje</div>
            <div className="flex items-center gap-1.5 rounded-full bg-yellow-400/15 px-3 py-1 font-black text-yellow-300">
              <Coins size={16} /> {save.coins}
            </div>
          </div>
          <div className="mt-4 flex flex-col gap-3">
            {UPGRADES.map(u => {
              const lvl = save.up[u.id];
              const cost = upgradeCost(lvl);
              const max = lvl >= MAX_LVL;
              const can = !max && save.coins >= cost;
              return (
                <div key={u.id} className="rounded-2xl border border-white/10 bg-white/5 p-3">
                  <div className="flex items-center gap-3">
                    <div className="grid h-10 w-10 place-items-center rounded-xl bg-gradient-to-br from-orange-400 to-red-600 text-white">{UP_ICON[u.id]}</div>
                    <div className="min-w-0 flex-1">
                      <div className="text-sm font-black">{u.name}</div>
                      <div className="truncate text-[11px] text-white/60">{u.desc}</div>
                    </div>
                    <button
                      disabled={!can}
                      onClick={() => onBuy(u.id)}
                      className={clsx(
                        'flex min-w-[84px] items-center justify-center gap-1 rounded-xl px-3 py-2 text-xs font-black transition',
                        max ? 'bg-emerald-500/20 text-emerald-200' : can ? 'bg-yellow-400 text-black hover:bg-yellow-300' : 'bg-white/10 text-white/40',
                      )}
                    >
                      {max ? 'MÁX' : <><Coins size={13} /> {cost}</>}
                    </button>
                  </div>
                  <div className="mt-2 flex gap-1">
                    {Array.from({ length: MAX_LVL }, (_, i) => (
                      <div key={i} className={clsx('h-1.5 flex-1 rounded-full', i < lvl ? 'bg-gradient-to-r from-yellow-300 to-orange-500' : 'bg-white/10')} />
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
          <div className="mt-3 text-center text-[11px] text-white/50">Gana monedas recogiéndolas, con mortales, saltos y cada 250 m.</div>
        </div>
      </div>
    </div>
  );
}

import { useEffect } from 'react';
import type { ReactNode } from 'react';
import confetti from 'canvas-confetti';
import { Coins, Home, Play, RotateCcw, Trophy, Wrench } from 'lucide-react';
import type { EndStats } from '../game/types';

const BTN = 'mt-font flex items-center justify-center gap-2 rounded-2xl border-b-4 px-6 py-3 text-base transition hover:scale-105 active:translate-y-0.5';

function Panel({ children }: { children: ReactNode }) {
  return (
    <div className="absolute inset-0 flex items-center justify-center bg-black/55 p-4 backdrop-blur-[3px]">
      <div className="w-full max-w-md rounded-3xl border border-orange-300/30 bg-gradient-to-b from-[#2a1030]/95 to-[#12081c]/95 p-6 text-center shadow-[0_20px_80px_rgba(0,0,0,.6)]">
        {children}
      </div>
    </div>
  );
}

export function PauseMenu({ onResume, onRestart, onMenu }: { onResume: () => void; onRestart: () => void; onMenu: () => void }) {
  return (
    <Panel>
      <div className="mt-font mt-title text-5xl italic">PAUSA</div>
      <div className="mt-2 text-xs uppercase tracking-widest text-orange-100/70">El motor sigue caliente</div>
      <div className="mt-6 flex flex-col gap-3">
        <button onClick={onResume} className={`${BTN} border-red-900 bg-gradient-to-b from-orange-400 to-red-600`}>
          <Play size={18} fill="currentColor" /> Continuar
        </button>
        <button onClick={onRestart} className={`${BTN} border-sky-950 bg-sky-700 hover:bg-sky-600`}>
          <RotateCcw size={18} /> Reiniciar
        </button>
        <button onClick={onMenu} className={`${BTN} border-slate-950 bg-slate-700 hover:bg-slate-600`}>
          <Home size={18} /> Menú
        </button>
      </div>
      <div className="mt-4 text-[11px] text-white/50">Pulsa P o Esc para continuar</div>
    </Panel>
  );
}

export function GameOver({ stats, onRetry, onMenu }: { stats: EndStats; onRetry: () => void; onMenu: () => void }) {
  useEffect(() => {
    if (!stats.newRecord) return;
    const t = window.setTimeout(() => {
      confetti({ particleCount: 150, spread: 90, origin: { y: 0.35 }, colors: ['#ffd23c', '#ff6a1c', '#d6281c', '#7dffa8', '#5ad1ff'] });
    }, 250);
    return () => window.clearTimeout(t);
  }, [stats.newRecord]);

  const rows: [string, string][] = [
    ['Zona', stats.zone],
    ['Distancia', `${stats.dist} m`],
    ['Monedas ganadas', `+${stats.coins}`],
    ['Mortales', String(stats.flips)],
    ['Mayor salto', `${stats.air.toFixed(1)} s`],
    ['Récord de la zona', `${stats.best} m`],
  ];
  return (
    <Panel>
      <div className="text-xs font-black uppercase tracking-[0.35em] text-orange-200/80">Fin de la carrera</div>
      <div className="mt-font mt-title mt-1 text-4xl italic md:text-5xl">{stats.reason}</div>
      {stats.newRecord && (
        <div className="mt-3 inline-flex items-center gap-2 rounded-full bg-emerald-400/20 px-4 py-1 text-sm font-black text-emerald-200">
          <Trophy size={16} /> ¡Nuevo récord!
        </div>
      )}
      <div className="mt-5 grid grid-cols-2 gap-2 text-left">
        {rows.map(([k, v]) => (
          <div key={k} className="rounded-xl bg-white/5 px-3 py-2">
            <div className="text-[10px] uppercase tracking-widest text-white/50">{k}</div>
            <div className="text-lg font-black">{v}</div>
          </div>
        ))}
      </div>
      <div className="mt-4 flex items-center justify-center gap-2 text-sm font-bold text-yellow-300">
        <Coins size={16} /> Monedero: {stats.wallet}
      </div>
      <div className="mt-5 flex flex-col gap-3 sm:flex-row">
        <button onClick={onRetry} className={`${BTN} flex-1 border-red-900 bg-gradient-to-b from-orange-400 to-red-600`}>
          <RotateCcw size={18} /> Jugar otra vez
        </button>
        <button onClick={onMenu} className={`${BTN} flex-1 border-slate-950 bg-slate-700 hover:bg-slate-600`}>
          <Wrench size={18} /> Garaje
        </button>
      </div>
    </Panel>
  );
}

import { useState } from 'react';
import { ChevronsLeft, ChevronsRight, Zap } from 'lucide-react';
import type { Input } from '../game/input';

/** Pedales táctiles: freno a la izquierda, gas y nitro a la derecha. */
export function TouchControls({ input }: { input: Input | null }) {
  const [touch] = useState(() => typeof window !== 'undefined' && ('ontouchstart' in window || navigator.maxTouchPoints > 0));
  const [gas, setGas] = useState(false);
  const [brake, setBrake] = useState(false);
  if (!touch || !input) return null;

  const pedal = (on: boolean) =>
    `pointer-events-auto flex h-28 w-24 touch-none flex-col items-center justify-center rounded-3xl border-2 text-[11px] font-black tracking-widest transition ${on ? 'scale-95 bg-white/30' : 'bg-black/35'}`;
  const setB = (v: boolean) => { input.touchBrake = v; setBrake(v); };
  const setG = (v: boolean) => { input.touchGas = v; setGas(v); };

  return (
    <div className="pointer-events-none absolute inset-x-0 bottom-16 flex items-end justify-between px-4">
      <button
        className={`${pedal(brake)} border-sky-300/60`}
        onPointerDown={e => { (e.target as HTMLElement).setPointerCapture?.(e.pointerId); setB(true); }}
        onPointerUp={() => setB(false)}
        onPointerCancel={() => setB(false)}
        onPointerLeave={() => setB(false)}
      >
        <ChevronsLeft size={30} /> FRENO
      </button>
      <div className="flex items-end gap-3">
        <button
          className="pointer-events-auto mb-2 grid h-16 w-16 place-items-center rounded-full border-2 border-sky-300/70 bg-sky-500/30 active:scale-90"
          onPointerDown={() => input.requestNitro()}
          aria-label="Nitro"
        >
          <Zap size={26} fill="currentColor" />
        </button>
        <button
          className={`${pedal(gas)} border-orange-300/70`}
          onPointerDown={e => { (e.target as HTMLElement).setPointerCapture?.(e.pointerId); setG(true); }}
          onPointerUp={() => setG(false)}
          onPointerCancel={() => setG(false)}
          onPointerLeave={() => setG(false)}
        >
          <ChevronsRight size={30} /> GAS
        </button>
      </div>
    </div>
  );
}

// Audio procedural con Web Audio: motor continuo (rpm), efectos y un ritmo de fondo sencillo.

class GameAudio {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private eng: { o1: OscillatorNode; o2: OscillatorNode; f: BiquadFilterNode; g: GainNode } | null = null;
  private noiseBuf: AudioBuffer | null = null;
  private musicTimer = 0;
  private step = 0;
  muted = false;

  init() {
    if (this.ctx) { void this.ctx.resume(); return; }
    const AC = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (!AC) return;
    const ctx = new AC();
    this.ctx = ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.5;
    this.master.connect(ctx.destination);
    const len = ctx.sampleRate;
    this.noiseBuf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = this.noiseBuf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    const o1 = ctx.createOscillator(), o2 = ctx.createOscillator();
    o1.type = 'sawtooth'; o2.type = 'square';
    const f = ctx.createBiquadFilter();
    f.type = 'lowpass'; f.frequency.value = 400; f.Q.value = 4;
    const g = ctx.createGain(); g.gain.value = 0;
    o1.connect(f); o2.connect(f); f.connect(g); g.connect(this.master);
    o1.start(); o2.start();
    this.eng = { o1, o2, f, g };
  }

  setMuted(m: boolean) {
    this.muted = m;
    if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.5, this.ctx.currentTime, 0.05);
  }

  /** rpm 0..1, gas 0..1; on=false silencia el motor. */
  engine(rpm: number, gas: number, on: boolean) {
    if (!this.ctx || !this.eng) return;
    const t = this.ctx.currentTime;
    const base = 38 + rpm * 95;
    this.eng.o1.frequency.setTargetAtTime(base, t, 0.05);
    this.eng.o2.frequency.setTargetAtTime(base * 0.5 + 3, t, 0.05);
    this.eng.f.frequency.setTargetAtTime(250 + rpm * 900 + gas * 500, t, 0.05);
    this.eng.g.gain.setTargetAtTime(on ? 0.07 + gas * 0.07 : 0, t, 0.08);
  }

  private tone(freq: number, dur: number, type: OscillatorType, vol: number, slide = 0, delay = 0) {
    if (!this.ctx || !this.master) return;
    const t = this.ctx.currentTime + delay;
    const o = this.ctx.createOscillator(), g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    o.connect(g); g.connect(this.master);
    o.start(t); o.stop(t + dur + 0.02);
  }

  private noise(dur: number, vol: number, freq: number, type: BiquadFilterType = 'lowpass') {
    if (!this.ctx || !this.master || !this.noiseBuf) return;
    const t = this.ctx.currentTime;
    const s = this.ctx.createBufferSource(); s.buffer = this.noiseBuf;
    const f = this.ctx.createBiquadFilter(); f.type = type; f.frequency.value = freq;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    s.connect(f); f.connect(g); g.connect(this.master);
    s.start(t); s.stop(t + dur);
  }

  coin(big = false) { this.tone(big ? 1320 : 988, 0.08, 'square', 0.06); this.tone(big ? 1760 : 1318, 0.12, 'square', 0.06, 0, 0.06); }
  fuel() { [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.12, 'triangle', 0.12, 0, i * 0.06)); }
  power() { this.tone(300, 0.35, 'sawtooth', 0.08, 900); }
  nitro() { this.noise(0.9, 0.25, 1800, 'bandpass'); this.tone(120, 0.6, 'sawtooth', 0.08, 300); }
  land(v: number) { this.tone(90, 0.18, 'sine', Math.min(0.35, v * 0.04), -50); this.noise(0.12, Math.min(0.2, v * 0.02), 500); }
  crate() { this.noise(0.18, 0.25, 1200, 'bandpass'); this.tone(180, 0.1, 'square', 0.06, -80); }
  boom() { this.noise(1.1, 0.5, 700); this.tone(70, 0.7, 'sine', 0.4, -40); }
  crash() { this.noise(0.7, 0.45, 2200); this.tone(110, 0.5, 'sawtooth', 0.15, -80); }
  trick() { [659, 784, 988, 1318].forEach((f, i) => this.tone(f, 0.16, 'square', 0.07, 0, i * 0.07)); }
  alarm() { this.tone(880, 0.12, 'square', 0.05); }

  startMusic() {
    if (!this.ctx || this.musicTimer) return;
    const bass = [55, 55, 65.4, 55, 73.4, 55, 65.4, 49];
    this.musicTimer = window.setInterval(() => {
      if (!this.ctx || this.ctx.state !== 'running') return;
      const i = this.step++ % 16;
      if (i % 2 === 0) this.tone(bass[(i / 2) % 8], 0.22, 'triangle', 0.09);
      if (i % 4 === 0) this.tone(60, 0.12, 'sine', 0.16, -30);
      if (i % 4 === 2) this.noise(0.06, 0.05, 6000, 'highpass');
    }, 150);
  }

  stopMusic() { window.clearInterval(this.musicTimer); this.musicTimer = 0; }
  dispose() { this.stopMusic(); if (this.ctx) void this.ctx.close(); this.ctx = null; this.master = null; this.eng = null; }
}

export const audio = new GameAudio();

// Motor del juego: bucle, cámara, reglas (combustible, trucos, choques), efectos y render.
import { audio } from './audio';
import type { Input } from './input';
import { Particles, PK } from './particles';
import { R, Truck } from './physics';
import type { Ctrl } from './physics';
import { drawDecor, drawParallax, drawSky, drawTerrain, drawWeather } from './render';
import { drawFlag, drawStartRamp, drawTruck } from './sprites';
import { Terrain } from './terrain';
import { loadSave, paramsFor, writeSave, zoneById, ZONES } from './types';
import type { EndStats, HudState, Save, Toast, TruckParams, Zone, ZoneId } from './types';
import { World } from './world';
import type { Hit } from './world';

export interface GameCallbacks { onHud(h: HudState): void; onEnd(s: EndStats): void; onToast(t: Toast): void }

const SUB = 1 / 480;
const CHECK = 250;

export class Game {
  private ctx: CanvasRenderingContext2D;
  private W = 1; private H = 1; private dpr = 1;
  private raf = 0; private last = 0; private t = 0;
  zone: Zone = ZONES[0];
  private terr = new Terrain(ZONES[0], 1);
  private truck = new Truck();
  private world = new World();
  private parts = new Particles();
  mode: 'attract' | 'play' | 'over' = 'attract';
  paused = false;
  private cam = { x: 0, y: 0, ppm: 40 };
  private shake = 0;
  private save: Save = loadSave();
  private p: TruckParams = paramsFor(this.save.up);
  private ctrl: Ctrl = { gas: 0, brake: 0, nitro: false };
  private fuel = 1; private coins = 0; private flips = 0; private maxAir = 0;
  private nitro = 0; private nitroT = 0; private magnetT = 0;
  private startX = 2; private dist = 0; private nextCheck = CHECK;
  private outT = 0; private crashT = 0; private hudT = 0; private alarmT = 0;
  private toastId = 0; private recordToast = false;

  constructor(private canvas: HTMLCanvasElement, private input: Input, private cb: GameCallbacks) {
    this.ctx = canvas.getContext('2d')!;
    this.setup('desierto', false);
  }

  resize(w: number, h: number) {
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.W = Math.max(1, w); this.H = Math.max(1, h);
    this.canvas.width = Math.round(this.W * this.dpr);
    this.canvas.height = Math.round(this.H * this.dpr);
  }

  private setup(zoneId: ZoneId, play: boolean) {
    this.zone = zoneById(zoneId);
    this.save = loadSave();
    this.p = paramsFor(play ? this.save.up : { engine: 2, suspension: 2, tires: 2, tank: 2 });
    this.terr = new Terrain(this.zone, play ? Math.floor(Math.random() * 1000) : 7);
    // Salida espectacular: el camión despega desde la rampa metálica
    this.truck.reset(this.startX + 0.4, this.terr.h(this.startX) + 5.3, 0.22, 13, 5);
    this.world.reset(this.terr, this.startX);
    this.parts.clear();
    Object.assign(this, { fuel: 1, coins: 0, flips: 0, maxAir: 0, nitro: 1, nitroT: 0, magnetT: 0, dist: 0, nextCheck: CHECK, outT: 0, crashT: 0, recordToast: false, shake: 0 });
    this.cam.x = this.truck.x + 3; this.cam.y = this.truck.y - 1;
  }

  setAttractZone(z: ZoneId) { if (this.mode !== 'play') { this.mode = 'attract'; this.setup(z, false); } }
  start(z: ZoneId) { this.setup(z, true); this.mode = 'play'; this.paused = false; this.emitHud(); }
  toAttract() { this.mode = 'attract'; this.paused = false; this.setup(this.zone.id, false); audio.engine(0, 0, false); }

  run() {
    const loop = (now: number) => {
      this.raf = requestAnimationFrame(loop);
      const dt = Math.min(0.05, Math.max(0, (now - (this.last || now)) / 1000));
      this.last = now;
      if (!this.paused) this.update(dt);
      else audio.engine(0, 0, false);
      this.render();
    };
    this.raf = requestAnimationFrame(loop);
  }

  destroy() { cancelAnimationFrame(this.raf); audio.engine(0, 0, false); }

  private toast(text: string, color: string, sub?: string) { this.cb.onToast({ id: ++this.toastId, text, color, sub }); }

  private autopilot(): Ctrl {
    const a = this.truck.a;
    if (!this.truck.grounded) return { gas: a < -0.2 ? 1 : 0, brake: a > 0.2 ? 1 : 0, nitro: false };
    return { gas: a > 0.75 ? 0 : 1, brake: 0, nitro: false };
  }

  private update(dt: number) {
    this.t += dt;
    const tr = this.truck, z = this.zone, play = this.mode === 'play';
    if (play && !tr.crashed) {
      this.ctrl = { gas: this.fuel > 0 ? this.input.gas() : 0, brake: this.input.brake(), nitro: false };
      if (this.input.consumeNitro() && this.nitro > 0 && this.nitroT <= 0) {
        this.nitro--; this.nitroT = 2.4; audio.nitro(); this.shake = Math.max(this.shake, 0.35);
        this.toast('¡NITRO!', '#5ad1ff');
      }
    } else this.ctrl = this.mode === 'attract' ? this.autopilot() : { gas: 0, brake: 0, nitro: false };
    this.nitroT = Math.max(0, this.nitroT - dt);
    this.magnetT = Math.max(0, this.magnetT - dt);
    this.ctrl.nitro = this.nitroT > 0;

    const n = Math.min(30, Math.ceil(dt / SUB));
    for (let i = 0; i < n; i++) tr.step(dt / n, this.ctrl, this.terr, z.gravity, this.p);
    tr.a = Math.atan2(Math.sin(tr.a), Math.cos(tr.a));

    if (play) {
      this.fuel = Math.max(0, this.fuel - (dt * (0.35 + 0.65 * this.ctrl.gas) * z.burn) / this.p.tank);
      this.dist = Math.max(this.dist, tr.x - this.startX);
      if (this.dist >= this.nextCheck) {
        this.coins += 10;
        this.toast(`¡${this.nextCheck} m!`, '#ffd23c', '+10 monedas');
        this.nextCheck += CHECK;
      }
      const best = this.save.best[z.id];
      if (!this.recordToast && best > 50 && this.dist > best) { this.recordToast = true; this.toast('¡Nuevo récord!', '#7dffa8'); audio.trick(); }
      if (this.fuel < 0.2 && this.fuel > 0 && (this.alarmT -= dt) < 0) { this.alarmT = 0.9; audio.alarm(); }
    }

    this.world.generate(tr.x + 90);
    this.handleHits(this.world.update(dt, tr, this.magnetT > 0));
    this.handleLanding();
    this.emitFx();

    if (tr.crashed && this.crashT === 0) {
      this.crashT = 0.001;
      this.shake = 1;
      const [hx, hy] = tr.local(0.1, 1.3);
      this.parts.burst(hx, hy, 40, 9, '#ffb03a', PK.Spark, 0.08, 0.6, 10);
      this.parts.burst(hx, hy, 20, 4, '#5a4a48', PK.Dust, 0.5, 1.2);
      if (play) audio.crash();
    }
    if (this.crashT > 0 && (this.crashT += dt) > 1.3) {
      if (play) this.finish('¡Volcaste!');
      else if (this.mode === 'attract') this.setup(z.id, false);
    }
    if (play && this.fuel <= 0 && tr.speed < 0.7) {
      if ((this.outT += dt) > 1.6) this.finish('Sin combustible');
    } else this.outT = 0;
    if (this.mode === 'attract' && tr.x > 1500) this.setup(z.id, false);

    // Cámara: adelanta en la dirección de avance y se aleja con la velocidad
    const ppm = (this.H / (16 + Math.min(9, tr.speed * 0.32))) * (this.W < 700 ? 0.78 : 1);
    this.cam.ppm += (ppm - this.cam.ppm) * Math.min(1, dt * 2);
    this.cam.x += (tr.x + Math.max(-3, Math.min(8, tr.vx * 0.5)) - this.cam.x) * Math.min(1, dt * 5);
    this.cam.y += (tr.y + 1 - this.cam.y) * Math.min(1, dt * 4);
    this.shake = Math.max(0, this.shake - dt * 2.2);
    this.parts.update(dt);

    const rpm = Math.min(1, Math.abs(tr.wheels[0].w + tr.wheels[1].w) / 2 / this.p.omegaMax);
    audio.engine(rpm, this.ctrl.gas, play && !tr.crashed);
    if (play && (this.hudT -= dt) <= 0) { this.hudT = 0.1; this.emitHud(); }
  }

  private handleHits(hits: Hit[]) {
    if (this.mode !== 'play') return;
    const tr = this.truck, P = this.parts;
    for (const h of hits) {
      switch (h.kind) {
        case 'coin': this.coins += 1; audio.coin(); P.burst(h.x, h.y, 6, 3, '#ffe066', PK.Glow, 0.25, 0.4); break;
        case 'gem': this.coins += 5; audio.coin(true); P.burst(h.x, h.y, 14, 4, '#ff6be0', PK.Glow, 0.3, 0.6); this.toast('+5', '#ff6be0'); break;
        case 'fuel': this.fuel = 1; audio.fuel(); P.burst(h.x, h.y, 18, 4, '#ff6040', PK.Glow, 0.35, 0.6); this.toast('¡Combustible lleno!', '#ff7b54'); break;
        case 'nitro': this.nitro = Math.min(3, this.nitro + 1); audio.power(); P.burst(h.x, h.y, 16, 4, '#5ad1ff', PK.Glow, 0.3, 0.6); this.toast('+1 Nitro', '#5ad1ff', 'Pulsa Espacio'); break;
        case 'magnet': this.magnetT = 10; audio.power(); P.burst(h.x, h.y, 16, 4, '#ff5068', PK.Glow, 0.3, 0.6); this.toast('¡Imán de monedas!', '#ff5068', '10 segundos'); break;
        case 'crate':
          tr.vx *= 0.86; this.coins += 2; this.shake = Math.max(this.shake, 0.3); audio.crate();
          P.burst(h.x, h.y, 14, 7, '#b8743a', PK.Debris, 0.35, 1.2, 18);
          break;
        case 'barrel': {
          const k = Math.sqrt(this.zone.gravity / 20) * 10;
          tr.vy += k; tr.w += (Math.random() - 0.5) * 3;
          for (const w of tr.wheels) w.vy += k;
          this.fuel = Math.max(0, this.fuel - 0.08);
          this.shake = 1.1; audio.boom();
          P.burst(h.x, h.y, 30, 7, '#ff8a2a', PK.Glow, 0.8, 0.8);
          P.burst(h.x, h.y, 30, 14, '#ffe08a', PK.Spark, 0.08, 0.7, 12);
          P.burst(h.x, h.y, 16, 3, '#3a3036', PK.Dust, 0.9, 1.6);
          this.toast('¡BOOM!', '#ff8a2a', '-8% combustible');
          break;
        }
      }
    }
  }

  private handleLanding() {
    const tr = this.truck;
    if (tr.impact > 5) {
      const v = tr.impact;
      this.shake = Math.max(this.shake, Math.min(0.8, v * 0.05));
      for (const w of tr.wheels) this.parts.burst(w.x, w.y - R * 0.8, Math.min(14, Math.floor(v)), 3, this.zone.dust, PK.Dust, 0.45, 0.9);
      if (this.mode === 'play') audio.land(v);
    }
    if (tr.scrape > 2) {
      const [x, y] = tr.local(0, -0.3);
      this.parts.burst(x, y, 4, 6, '#ffc060', PK.Spark, 0.06, 0.3, 10);
    }
    tr.impact = tr.scrape = 0;
    const L = tr.landing;
    tr.landing = null;
    if (!L || this.mode !== 'play' || tr.crashed) return;
    this.maxAir = Math.max(this.maxAir, L.t);
    const n = Math.floor((Math.abs(L.rot) + 0.7) / (Math.PI * 2));
    if (n >= 1) {
      this.flips += n;
      this.coins += 25 * n;
      audio.trick();
      this.toast(`${L.rot > 0 ? 'Mortal atrás' : 'Mortal adelante'}${n > 1 ? ' x' + n : ''}`, '#b388ff', `+${25 * n} monedas`);
    } else if (L.t > 1.3) {
      const b = Math.floor(L.t * 4);
      this.coins += b;
      this.toast(`¡Gran salto! ${L.t.toFixed(1)} s`, '#5ad1ff', `+${b} monedas`);
    }
  }

  private emitFx() {
    const tr = this.truck, P = this.parts;
    for (const w of tr.wheels) {
      if (w.contact && Math.random() < Math.min(0.9, Math.abs(w.slip) * 0.12 + tr.speed * 0.03)) {
        P.emit(w.x - 0.2, w.y - R * 0.85, -tr.vx * 0.15 - Math.sign(w.slip) * 2 + (Math.random() - 0.5), 1 + Math.random() * 2.5, 0.9, 0.3 + Math.random() * 0.25, this.zone.dust, PK.Dust);
      }
    }
    if (this.ctrl.gas > 0 && Math.random() < 0.6) {
      const [x, y] = tr.local(-1.17, 1.5);
      P.emit(x, y, -1 + Math.random() * 0.5, 1.5, 0.9, 0.18, 'rgba(70,70,80,0.8)', PK.Dust);
    }
    if (this.nitroT > 0) {
      const [x, y] = tr.local(-2.3, 0.05);
      for (let i = 0; i < 2; i++) P.emit(x, y, -tr.vx * 0.2 - 4 + Math.random() * 2, (Math.random() - 0.5) * 2, 0.35, 0.35, i ? '#7fd8ff' : '#3a6bff', PK.Glow);
    }
  }

  private finish(reason: string) {
    if (this.mode !== 'play') return;
    this.mode = 'over';
    audio.engine(0, 0, false);
    const s = loadSave();
    const dist = Math.floor(this.dist);
    const newRecord = dist > s.best[this.zone.id];
    if (newRecord) s.best[this.zone.id] = dist;
    s.coins += this.coins;
    writeSave(s);
    this.save = s;
    this.cb.onEnd({ reason, dist, coins: this.coins, flips: this.flips, air: this.maxAir, best: s.best[this.zone.id], newRecord, wallet: s.coins, zone: this.zone.name });
  }

  private emitHud() {
    const tr = this.truck;
    this.cb.onHud({
      dist: Math.floor(this.dist), best: this.save.best[this.zone.id], coins: this.coins, fuel: this.fuel,
      speed: Math.round(Math.abs(tr.vx) * 3.6), nitro: this.nitro, nitroOn: this.nitroT > 0, magnet: this.magnetT,
      air: !tr.grounded, zone: this.zone.name, next: this.nextCheck,
    });
  }

  private render() {
    const { ctx, W, H, cam, zone: z, t } = this;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    drawSky(ctx, W, H, z, t, cam.x);
    drawParallax(ctx, W, H, z, cam.x, cam.y);
    const ppm = cam.ppm, ax = W * 0.42, ay = H * 0.58;
    const x0 = cam.x - ax / ppm - 1, x1 = cam.x + (W - ax) / ppm + 1;
    ctx.save();
    ctx.translate(ax + (Math.random() - 0.5) * this.shake * 18, ay + (Math.random() - 0.5) * this.shake * 18);
    ctx.scale(ppm, -ppm);
    ctx.translate(-cam.x, -cam.y);
    drawDecor(ctx, this.terr, x0, x1);
    const best = this.save.best[z.id];
    const fx = this.startX + best, cx = this.startX + this.nextCheck;
    if (best > 20 && fx > x0 - 3 && fx < x1 + 3) drawFlag(ctx, fx, this.terr.h(fx), t, '#7dffa8');
    if (this.mode === 'play' && cx < x1 + 3) drawFlag(ctx, cx, this.terr.h(cx), t, '#ffd23c');
    if (x0 < this.startX + 2) drawStartRamp(ctx, this.startX, this.terr.h(this.startX), t);
    drawTerrain(ctx, this.terr, x0, x1, cam.y - (H - ay) / ppm - 2, ppm);
    this.world.draw(ctx, t, x0, x1);
    drawTruck(ctx, this.truck, t, this.nitroT > 0, this.ctrl.gas);
    this.parts.draw(ctx);
    ctx.restore();
    drawWeather(ctx, W, H, z, t, cam.x, this.nitroT > 0);
  }
}

// Entrada: teclado en window + pedales táctiles.

const BLOCK = new Set(['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space']);
const GAS = ['ArrowRight', 'ArrowUp', 'KeyD', 'KeyW'];
const BRAKE = ['ArrowLeft', 'ArrowDown', 'KeyA', 'KeyS'];
const NITRO = new Set(['Space', 'ShiftLeft', 'ShiftRight', 'KeyN']);

export class Input {
  keys = new Set<string>();
  touchGas = false;
  touchBrake = false;
  private nitroReq = false;

  private onDown = (e: KeyboardEvent) => {
    if (BLOCK.has(e.code)) e.preventDefault();
    if (!e.repeat && NITRO.has(e.code)) this.nitroReq = true;
    this.keys.add(e.code);
  };
  private onUp = (e: KeyboardEvent) => { this.keys.delete(e.code); };
  private onBlur = () => { this.keys.clear(); this.touchGas = this.touchBrake = false; };

  attach() { this.listen(true); }
  detach() { this.listen(false); }
  private listen(on: boolean) {
    const f = (on ? window.addEventListener : window.removeEventListener).bind(window);
    f('keydown', this.onDown as EventListener); f('keyup', this.onUp as EventListener); f('blur', this.onBlur);
  }

  gas() { return this.touchGas || GAS.some(k => this.keys.has(k)) ? 1 : 0; }
  brake() { return this.touchBrake || BRAKE.some(k => this.keys.has(k)) ? 1 : 0; }
  requestNitro() { this.nitroReq = true; }
  consumeNitro() { const r = this.nitroReq; this.nitroReq = false; return r; }
}

// Sistema de partículas con pool fijo. Se dibuja en coordenadas de mundo (metros, y hacia arriba).

export const PK = { Dust: 0, Spark: 1, Debris: 2, Glow: 3 } as const;
export type PKind = 0 | 1 | 2 | 3;

interface P { x: number; y: number; vx: number; vy: number; life: number; max: number; size: number; color: string; kind: PKind; g: number; rot: number; on: boolean }

const N = 520;

export class Particles {
  private pool: P[] = Array.from({ length: N }, () => ({ x: 0, y: 0, vx: 0, vy: 0, life: 0, max: 1, size: 1, color: '#fff', kind: PK.Dust as PKind, g: 0, rot: 0, on: false }));
  private next = 0;

  emit(x: number, y: number, vx: number, vy: number, life: number, size: number, color: string, kind: PKind = PK.Dust, g = 0) {
    const p = this.pool[this.next];
    this.next = (this.next + 1) % N;
    Object.assign(p, { x, y, vx, vy, life, max: life, size, color, kind, g, rot: Math.random() * 6, on: true });
  }

  burst(x: number, y: number, n: number, speed: number, color: string, kind: PKind, size: number, life: number, g = 0) {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const v = speed * (0.3 + Math.random() * 0.7);
      this.emit(x, y, Math.cos(a) * v, Math.sin(a) * v + speed * 0.3, life * (0.6 + Math.random() * 0.6), size * (0.6 + Math.random() * 0.8), color, kind, g);
    }
  }

  clear() { for (const p of this.pool) p.on = false; }

  update(dt: number) {
    for (const p of this.pool) {
      if (!p.on) continue;
      p.life -= dt;
      if (p.life <= 0) { p.on = false; continue; }
      p.vy -= p.g * dt;
      const drag = p.kind === PK.Dust ? 1.6 : 0.4;
      p.vx *= 1 - drag * dt; p.vy *= 1 - drag * dt;
      p.x += p.vx * dt; p.y += p.vy * dt;
      p.rot += dt * 6;
    }
  }

  draw(ctx: CanvasRenderingContext2D) {
    for (const pass of [0, 1]) {
      ctx.globalCompositeOperation = pass ? 'lighter' : 'source-over';
      for (const p of this.pool) {
        if (!p.on) continue;
        const add = p.kind === PK.Spark || p.kind === PK.Glow;
        if (add !== (pass === 1)) continue;
        const k = p.life / p.max;
        ctx.globalAlpha = Math.min(1, k * 1.4);
        ctx.fillStyle = ctx.strokeStyle = p.color;
        if (p.kind === PK.Dust) {
          ctx.globalAlpha = k * 0.55;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size * (1.6 - k * 0.8), 0, Math.PI * 2);
          ctx.fill();
        } else if (p.kind === PK.Spark) {
          ctx.lineWidth = p.size;
          ctx.beginPath();
          ctx.moveTo(p.x, p.y);
          ctx.lineTo(p.x - p.vx * 0.04, p.y - p.vy * 0.04);
          ctx.stroke();
        } else if (p.kind === PK.Debris) {
          ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.rot);
          ctx.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2);
          ctx.restore();
        } else {
          ctx.globalAlpha = k * 0.8;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size * (0.5 + k * 0.6), 0, Math.PI * 2);
          ctx.fill();
        }
      }
    }
    ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  }
}

// Física del camión: chasis rígido + 2 ruedas unidas por resortes amortiguados (suspensión).
// Unidades: metros, segundos; y hacia arriba; ángulo del chasis antihorario.
import type { Terrain } from './terrain';
import type { TruckParams } from './types';

export interface Wheel { x: number; y: number; vx: number; vy: number; ang: number; w: number; contact: boolean; slip: number }
export interface Ctrl { gas: number; brake: number; nitro: boolean }

export const M = 4.2;
export const INERTIA = 4.6;
export const MW = 0.6;
export const R = 0.86;
const IW = 0.5 * MW * R * R;
export const REST = 0.8;
const MIN_L = 0.32;
const MAX_L = 1.15;
const KT = 7000;
const CT = 90;
export const ANCH_X = [-1.32, 1.32];
export const ANCH_Y = -0.2;
const HULL: [number, number][] = [[-1.85, -0.25], [1.95, -0.2], [-1.85, 0.6], [1.9, 0.5], [-0.75, 1.3], [0.9, 1.3]];
export const HEAD: [number, number] = [0.1, 1.42];

export class Truck {
  x = 0; y = 0; vx = 0; vy = 0; a = 0; w = 0;
  wheels: Wheel[] = [];
  crashed = false; grounded = true;
  airTime = 0; airRot = 0; impact = 0; scrape = 0;
  assist = 0; // segundos sin control aéreo (salto de salida)
  landing: { t: number; rot: number } | null = null;

  constructor(x = 0, y = 0) { this.reset(x, y); }

  reset(x: number, y: number, a = 0, vx = 0, vy = 0) {
    Object.assign(this, { x, y, vx, vy, a, w: -0.25, assist: vy > 0 ? 1.2 : 0, crashed: false, grounded: false, airTime: 0, airRot: 0, impact: 0, scrape: 0, landing: null });
    this.wheels = ANCH_X.map(lx => {
      const [wx, wy] = this.local(lx, ANCH_Y - REST);
      return { x: wx, y: wy, vx, vy, ang: 0, w: vx / R, contact: false, slip: 0 };
    });
  }

  local(lx: number, ly: number): [number, number] {
    const c = Math.cos(this.a), s = Math.sin(this.a);
    return [this.x + lx * c - ly * s, this.y + lx * s + ly * c];
  }

  get speed() { return Math.hypot(this.vx, this.vy); }

  step(h: number, ctrl: Ctrl, terr: Terrain, g: number, p: TruckParams) {
    const c = Math.cos(this.a), s = Math.sin(this.a);
    const ux = s, uy = -c, tx = c, ty = s;
    this.vy -= g * h;
    if (ctrl.nitro) { this.vx += tx * 16 * h; this.vy += ty * 16 * h; }

    // --- Suspensión ---
    for (let i = 0; i < 2; i++) {
      const wh = this.wheels[i];
      wh.vy -= g * h;
      const lx = ANCH_X[i];
      const ax = this.x + lx * c - ANCH_Y * s, ay = this.y + lx * s + ANCH_Y * c;
      const rx = ax - this.x, ry = ay - this.y;
      const vax = this.vx - this.w * ry, vay = this.vy + this.w * rx;
      const dx = wh.x - ax, dy = wh.y - ay;
      const du = dx * ux + dy * uy, dt = dx * tx + dy * ty;
      const rvx = wh.vx - vax, rvy = wh.vy - vay;
      const rvu = rvx * ux + rvy * uy, rvt = rvx * tx + rvy * ty;
      const fu = -p.k * (du - REST) - p.c * rvu;
      const ft = -KT * dt - CT * rvt;
      const fx = ux * fu + tx * ft, fy = uy * fu + ty * ft;
      wh.vx += (fx / MW) * h; wh.vy += (fy / MW) * h;
      this.vx -= (fx / M) * h; this.vy -= (fy / M) * h;
      this.w -= ((rx * fy - ry * fx) / INERTIA) * h;
      if (du > MAX_L || du < MIN_L) {
        const corr = du - (du > MAX_L ? MAX_L : MIN_L);
        wh.x -= ux * corr * 0.75; wh.y -= uy * corr * 0.75;
        this.x += ux * corr * 0.25; this.y += uy * corr * 0.25;
        if ((du > MAX_L && rvu > 0) || (du < MIN_L && rvu < 0)) {
          const j = rvu / (1 / MW + 1 / M);
          wh.vx -= (ux * j) / MW; wh.vy -= (uy * j) / MW;
          this.vx += (ux * j) / M; this.vy += (uy * j) / M;
          this.w += ((rx * uy - ry * ux) * j * 0.5) / INERTIA;
          if (du < MIN_L) this.impact = Math.max(this.impact, -rvu);
        }
      }
    }

    // --- Motor y frenos ---
    const omax = p.omegaMax * (ctrl.nitro ? 1.35 : 1);
    for (const wh of this.wheels) {
      if (ctrl.gas > 0 && wh.w < omax) {
        const T = p.torque * ctrl.gas * (1 - Math.max(0, wh.w) / omax);
        wh.w += (T / IW) * h;
        this.w += (T * 0.1 / INERTIA) * h;
      }
      if (ctrl.brake > 0) {
        if (wh.w > 1.5) wh.w -= 70 * ctrl.brake * h;
        else if (wh.w > -omax * 0.45) {
          const T = p.torque * 0.7 * ctrl.brake;
          wh.w -= (T / IW) * h;
          this.w -= (T * 0.1 / INERTIA) * h;
        }
      }
      wh.w *= 1 - 0.3 * h;
    }

    // --- Contacto rueda-suelo con fricción limitada (impulsos) ---
    let any = false;
    for (const wh of this.wheels) {
      const gh = terr.h(wh.x), sl = terr.slope(wh.x);
      const inv = 1 / Math.sqrt(1 + sl * sl);
      const nx = -sl * inv, ny = inv;
      const pen = R - (wh.y - gh) * ny;
      wh.contact = pen > -0.04;
      if (wh.contact) any = true;
      if (pen <= 0) continue;
      wh.x += nx * pen; wh.y += ny * pen;
      const vn = wh.vx * nx + wh.vy * ny;
      let jn = 0;
      if (vn < 0) {
        jn = -vn * MW;
        wh.vx -= nx * vn; wh.vy -= ny * vn;
        this.impact = Math.max(this.impact, -vn * 0.6);
      }
      const t2x = ny, t2y = -nx;
      const slip = wh.vx * t2x + wh.vy * t2y - wh.w * R;
      const lim = p.mu * terr.gripAt(wh.x) * (jn + MW * g * h * 0.3);
      const jt = Math.max(-lim, Math.min(lim, -slip / (1 / MW + (R * R) / IW)));
      wh.vx += (t2x * jt) / MW; wh.vy += (t2y * jt) / MW;
      wh.w -= (jt * R) / IW;
      wh.slip = slip;
    }

    // --- Casco del chasis contra el suelo ---
    for (const [lx, ly] of HULL) {
      const [px, py] = this.local(lx, ly);
      const gh = terr.h(px), sl = terr.slope(px);
      const inv = 1 / Math.sqrt(1 + sl * sl);
      const nx = -sl * inv, ny = inv;
      const pen = (gh - py) * ny;
      if (pen <= 0) continue;
      any = true;
      if (Math.cos(this.a) < -0.2) this.crashed = true;
      const rx = px - this.x, ry = py - this.y;
      this.x += nx * pen * 0.8; this.y += ny * pen * 0.8;
      const vpx = this.vx - this.w * ry, vpy = this.vy + this.w * rx;
      const vn = vpx * nx + vpy * ny;
      if (vn >= 0) continue;
      const rn = rx * ny - ry * nx;
      const j = (-1.15 * vn) / (1 / M + (rn * rn) / INERTIA);
      this.vx += (nx * j) / M; this.vy += (ny * j) / M; this.w += (rn * j) / INERTIA;
      const vt = vpx * ny - vpy * nx;
      const rt = -rx * nx - ry * ny;
      const jf = Math.max(-0.5 * j, Math.min(0.5 * j, -vt / (1 / M + (rt * rt) / INERTIA)));
      this.vx += (ny * jf) / M; this.vy -= (nx * jf) / M; this.w += (rt * jf) / INERTIA;
      this.scrape = Math.max(this.scrape, Math.abs(vt));
    }
    const [hx, hy] = this.local(HEAD[0], HEAD[1]);
    if (hy < terr.h(hx) + 0.05) this.crashed = true;

    // --- Control aéreo y trucos ---
    this.assist = Math.max(0, this.assist - h);
    if (!any) {
      if (this.assist <= 0) this.w += (ctrl.gas - ctrl.brake) * 4.6 * h;
      this.airTime += h;
      this.airRot += this.w * h;
    } else if (this.airTime > 0) {
      if (this.airTime > 0.45) this.landing = { t: this.airTime, rot: this.airRot };
      this.airTime = this.airRot = 0;
    }
    this.grounded = any;
    this.w = Math.max(-9, Math.min(9, this.w));

    // --- Integración ---
    this.x += this.vx * h; this.y += this.vy * h; this.a += this.w * h;
    for (const wh of this.wheels) { wh.x += wh.vx * h; wh.y += wh.vy * h; wh.ang -= wh.w * h; }
  }
}

// Fondo (cielo, sol/Tierra, auroras, estrellas), montañas en parallax, terreno, decorados y clima.
import { hash, noise1 } from './terrain';
import type { Terrain } from './terrain';
import type { Zone } from './types';

const STARS = Array.from({ length: 140 }, (_, i) => ({ x: hash(i, 1), y: hash(i, 2), r: 0.4 + hash(i, 3) * 1.4, p: hash(i, 4) * 6 }));
const FLAKES = Array.from({ length: 130 }, (_, i) => ({ x: hash(i, 5), y: hash(i, 6), s: 0.4 + hash(i, 7), p: hash(i, 8) * 6 }));

export function drawSky(ctx: CanvasRenderingContext2D, W: number, H: number, z: Zone, t: number, camX: number) {
  const g = ctx.createLinearGradient(0, 0, 0, H * 0.75);
  g.addColorStop(0, z.sky[0]); g.addColorStop(0.55, z.sky[1]); g.addColorStop(1, z.sky[2]);
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  if (z.weather !== 'dust') {
    for (const s of STARS) {
      const sx = ((s.x * W * 1.2 - camX * 0.6) % (W * 1.2) + W * 1.2) % (W * 1.2) - W * 0.1;
      const lim = z.weather === 'stars' ? 0.85 : 0.42;
      if (s.y > lim) continue;
      ctx.globalAlpha = (z.weather === 'stars' ? 0.9 : 0.5) * (0.55 + 0.45 * Math.sin(t * 2 + s.p));
      ctx.fillStyle = '#fff';
      ctx.fillRect(sx, s.y * H, s.r, s.r);
    }
    ctx.globalAlpha = 1;
  }

  if (z.weather === 'snow') drawAurora(ctx, W, H, t);

  const sx = W * 0.7, sy = H * (z.weather === 'stars' ? 0.24 : 0.36), sr = Math.min(W, H) * (z.weather === 'stars' ? 0.085 : 0.11);
  const glow = ctx.createRadialGradient(sx, sy, sr * 0.4, sx, sy, sr * 4.5);
  glow.addColorStop(0, z.sunGlow); glow.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = glow; ctx.fillRect(0, 0, W, H);

  if (z.weather === 'stars') {
    // La Tierra vista desde la Luna
    ctx.save();
    ctx.beginPath(); ctx.arc(sx, sy, sr, 0, Math.PI * 2); ctx.clip();
    const eg = ctx.createRadialGradient(sx - sr * 0.4, sy - sr * 0.4, sr * 0.1, sx, sy, sr);
    eg.addColorStop(0, '#8fd0ff'); eg.addColorStop(1, '#1f58c9');
    ctx.fillStyle = eg; ctx.fillRect(sx - sr, sy - sr, sr * 2, sr * 2);
    ctx.fillStyle = '#4fb36b';
    for (let i = 0; i < 5; i++) {
      ctx.beginPath(); ctx.ellipse(sx + (hash(i, 40) - 0.5) * sr * 1.6 + t * 2 % (sr * 2) - sr * 0.3, sy + (hash(i, 41) - 0.5) * sr * 1.4, sr * (0.18 + hash(i, 42) * 0.3), sr * 0.14, hash(i, 43) * 3, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.fillStyle = 'rgba(0,0,20,0.55)';
    ctx.beginPath(); ctx.arc(sx + sr * 0.55, sy + sr * 0.2, sr * 1.05, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
    return;
  }
  // Sol retro con franjas
  ctx.save();
  ctx.beginPath(); ctx.arc(sx, sy, sr, 0, Math.PI * 2); ctx.clip();
  const sg = ctx.createLinearGradient(0, sy - sr, 0, sy + sr);
  sg.addColorStop(0, z.sun); sg.addColorStop(1, z.weather === 'dust' ? '#ff6a4a' : '#ffc0d6');
  ctx.fillStyle = sg; ctx.fillRect(sx - sr, sy - sr, sr * 2, sr * 2);
  ctx.globalCompositeOperation = 'destination-out';
  for (let i = 0; i < 6; i++) ctx.fillRect(sx - sr, sy + sr * (0.1 + i * 0.16), sr * 2, 1.5 + i * 1.6);
  ctx.restore();
}

function drawAurora(ctx: CanvasRenderingContext2D, W: number, H: number, t: number) {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (let b = 0; b < 3; b++) {
    const g = ctx.createLinearGradient(0, H * 0.05, 0, H * 0.4);
    g.addColorStop(0, 'rgba(80,255,190,0)'); g.addColorStop(1, 'rgba(80,255,190,0)');
    g.addColorStop(0.5, b === 1 ? 'rgba(140,90,255,0.16)' : 'rgba(70,255,180,0.18)');
    ctx.fillStyle = g;
    ctx.beginPath();
    for (let x = 0; x <= W; x += 16) {
      const y = H * (0.14 + b * 0.06) + Math.sin(x * 0.006 + t * 0.4 + b * 2) * H * 0.05 + noise1(x * 0.01 + t * 0.2, b) * H * 0.03;
      if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    for (let x = W; x >= 0; x -= 16) ctx.lineTo(x, H * (0.3 + b * 0.05) + Math.sin(x * 0.005 + t * 0.3 + b) * H * 0.04);
    ctx.fill();
  }
  ctx.restore();
}

/** Tres capas de montañas con parallax, más bruma atmosférica. */
export function drawParallax(ctx: CanvasRenderingContext2D, W: number, H: number, z: Zone, camX: number, camY: number) {
  const F = [0.06, 0.16, 0.32];
  const BASE = [0.5, 0.58, 0.67];
  const AMP = [0.2, 0.16, 0.12];
  for (let i = 0; i < 3; i++) {
    const base = H * BASE[i] + Math.min(H * 0.12, Math.max(-H * 0.12, camY * 6 * F[i]));
    ctx.fillStyle = z.hills[i];
    ctx.beginPath();
    ctx.moveTo(0, H);
    for (let sx = 0; sx <= W + 8; sx += 8) {
      const wx = (sx + camX * 40 * F[i]) / (130 - i * 25);
      let n = noise1(wx, 50 + i) * 0.7 + noise1(wx * 2.7, 60 + i) * 0.3;
      if (z.deco === 'cactus') n = Math.min(n, 0.25 + i * 0.1) + (n > 0.25 ? 0.02 : 0);
      else if (z.deco === 'pine') n = 1 - Math.abs(n) * 2.2 + noise1(wx * 6, 70 + i) * 0.08;
      ctx.lineTo(sx, base - n * H * AMP[i]);
    }
    ctx.lineTo(W, H);
    ctx.fill();
    if (z.deco === 'pine' && i < 2) { ctx.fillStyle = 'rgba(255,255,255,0.12)'; ctx.fill(); }
    const haze = ctx.createLinearGradient(0, base - H * 0.08, 0, base + H * 0.25);
    haze.addColorStop(0, 'rgba(0,0,0,0)'); haze.addColorStop(1, z.sky[2] + '66');
    ctx.fillStyle = haze; ctx.fillRect(0, base - H * 0.08, W, H);
  }
}

/** Terreno en coordenadas de mundo (la transformación ya está aplicada). */
export function drawTerrain(ctx: CanvasRenderingContext2D, terr: Terrain, x0: number, x1: number, yBot: number, ppm: number) {
  const z = terr.zone;
  const step = Math.max(0.25, 5 / ppm);
  const pts: number[] = [];
  for (let x = Math.floor(x0 / step) * step; x <= x1 + step; x += step) pts.push(x, terr.h(x));
  const path = new Path2D();
  path.moveTo(pts[0], yBot);
  for (let i = 0; i < pts.length; i += 2) path.lineTo(pts[i], pts[i + 1]);
  path.lineTo(pts[pts.length - 2], yBot);
  path.closePath();
  const top = new Path2D();
  for (let i = 0; i < pts.length; i += 2) i ? top.lineTo(pts[i], pts[i + 1]) : top.moveTo(pts[i], pts[i + 1]);

  let ymax = -1e9;
  for (let i = 1; i < pts.length; i += 2) ymax = Math.max(ymax, pts[i]);
  const g = ctx.createLinearGradient(0, ymax, 0, yBot);
  g.addColorStop(0, z.ground[1]); g.addColorStop(0.6, z.ground[2]);
  ctx.fillStyle = g;
  ctx.fill(path);

  // Estratos
  ctx.save();
  ctx.clip(path);
  ctx.lineJoin = 'round';
  ctx.lineWidth = 0.35;
  for (let k = 1; k <= 3; k++) { ctx.translate(0, -1.3 * k); ctx.strokeStyle = `rgba(0,0,0,${0.1 + k * 0.03})`; ctx.stroke(top); ctx.translate(0, 1.3 * k); }
  // Piedras incrustadas
  ctx.fillStyle = 'rgba(0,0,0,0.13)';
  for (let c = Math.floor(x0 / 3); c < x1 / 3; c++) {
    const x = c * 3 + hash(c, 90) * 3;
    ctx.beginPath(); ctx.ellipse(x, terr.h(x) - 0.8 - hash(c, 91) * 4, 0.25 + hash(c, 92) * 0.4, 0.15 + hash(c, 93) * 0.2, 0, 0, Math.PI * 2); ctx.fill();
  }
  ctx.restore();

  ctx.lineCap = 'round';
  ctx.strokeStyle = z.ground[0]; ctx.lineWidth = 0.7;
  ctx.save(); ctx.translate(0, -0.25); ctx.stroke(top); ctx.restore();
  ctx.strokeStyle = z.edge; ctx.lineWidth = 0.1; ctx.stroke(top);

  if (z.id === 'nieve') {
    ctx.strokeStyle = 'rgba(150,230,255,0.9)'; ctx.lineWidth = 0.32;
    for (let c = Math.floor(x0 / 34); c <= x1 / 34; c++) {
      const sx = c * 34;
      if (!terr.isIce(sx + 1)) continue;
      ctx.beginPath();
      for (let x = sx; x <= sx + 16; x += 0.5) x === sx ? ctx.moveTo(x, terr.h(x) + 0.05) : ctx.lineTo(x, terr.h(x) + 0.05);
      ctx.stroke();
    }
  }
}

/** Decorados del primer plano trasero: cactus, pinos o rocas lunares. */
export function drawDecor(ctx: CanvasRenderingContext2D, terr: Terrain, x0: number, x1: number) {
  const z = terr.zone;
  for (let c = Math.floor(x0 / 6) - 1; c < x1 / 6 + 1; c++) {
    if (hash(c, terr.seed + 60) < 0.45) continue;
    const x = c * 6 + hash(c, terr.seed + 61) * 4;
    const y = terr.h(x) - 0.1;
    const s = 0.7 + hash(c, terr.seed + 62) * 0.8;
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(s, s);
    if (z.deco === 'cactus') {
      ctx.fillStyle = '#2f6b45'; ctx.strokeStyle = '#1d4430'; ctx.lineWidth = 0.08;
      const arm = (dx: number, h: number) => {
        ctx.beginPath(); ctx.roundRect(dx - 0.16, 1.0, 0.32, h, 0.16); ctx.fill(); ctx.stroke();
        ctx.beginPath(); ctx.roundRect(dx > 0 ? 0 : dx, 0.95, Math.abs(dx) + 0.16, 0.3, 0.15); ctx.fill();
      };
      arm(-0.55, 1.0 + hash(c, 3) * 0.6);
      if (hash(c, 4) > 0.3) arm(0.55, 0.7 + hash(c, 5) * 0.8);
      ctx.beginPath(); ctx.roundRect(-0.22, 0, 0.44, 2.6, 0.22); ctx.fill(); ctx.stroke();
      ctx.fillStyle = 'rgba(255,255,255,0.12)'; ctx.fillRect(-0.12, 0.2, 0.08, 2.2);
    } else if (z.deco === 'pine') {
      ctx.fillStyle = '#4a3428'; ctx.fillRect(-0.12, 0, 0.24, 0.6);
      for (let k = 0; k < 3; k++) {
        const yb = 0.5 + k * 0.75, w = 1.2 - k * 0.3;
        ctx.fillStyle = '#1f4a4f';
        ctx.beginPath(); ctx.moveTo(-w, yb); ctx.lineTo(w, yb); ctx.lineTo(0, yb + 1.3); ctx.fill();
        ctx.fillStyle = '#f4f8ff';
        ctx.beginPath(); ctx.moveTo(-w * 0.45, yb + 0.75); ctx.lineTo(w * 0.45, yb + 0.75); ctx.lineTo(0, yb + 1.3); ctx.fill();
      }
    } else {
      ctx.fillStyle = '#6d7086';
      ctx.beginPath(); ctx.moveTo(-0.9, -0.2); ctx.lineTo(-0.7, 0.5); ctx.lineTo(-0.1, 0.85); ctx.lineTo(0.6, 0.6); ctx.lineTo(0.95, -0.2); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.25)';
      ctx.beginPath(); ctx.moveTo(-0.7, 0.5); ctx.lineTo(-0.1, 0.85); ctx.lineTo(-0.2, 0.4); ctx.fill();
    }
    ctx.restore();
  }
}

/** Clima en espacio de pantalla. */
export function drawWeather(ctx: CanvasRenderingContext2D, W: number, H: number, z: Zone, t: number, camX: number, nitro: boolean) {
  if (z.weather === 'snow') {
    ctx.fillStyle = '#fff';
    for (const f of FLAKES) {
      const x = (((f.x * W - camX * 30 * f.s + Math.sin(t + f.p) * 20) % W) + W) % W;
      const y = (f.y * H + t * 60 * f.s) % H;
      ctx.globalAlpha = 0.4 + f.s * 0.4;
      ctx.beginPath(); ctx.arc(x, y, 1 + f.s * 2, 0, Math.PI * 2); ctx.fill();
    }
  } else if (z.weather === 'dust') {
    ctx.fillStyle = '#ffd9a0';
    for (const f of FLAKES) {
      if (f.s > 0.9) continue;
      const x = (((f.x * W - camX * 40 * f.s - t * 30) % W) + W) % W;
      const y = f.y * H + Math.sin(t * 0.8 + f.p) * 12;
      ctx.globalAlpha = 0.25;
      ctx.fillRect(x, y, 2, 2);
    }
  }
  ctx.globalAlpha = 1;
  if (nitro) {
    ctx.strokeStyle = 'rgba(160,230,255,0.35)'; ctx.lineWidth = 2;
    for (let i = 0; i < 18; i++) {
      const y = hash(i, Math.floor(t * 20)) * H;
      const x = hash(i + 50, Math.floor(t * 20)) * W;
      ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x - 120, y); ctx.stroke();
    }
  }
  const v = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.45, W / 2, H / 2, Math.max(W, H) * 0.8);
  v.addColorStop(0, 'rgba(0,0,0,0)'); v.addColorStop(1, 'rgba(0,0,0,0.45)');
  ctx.fillStyle = v; ctx.fillRect(0, 0, W, H);
}

// Dibujo vectorial del monster truck y de los objetos, en coordenadas de mundo (metros, y hacia arriba).
import { ANCH_X, ANCH_Y, R } from './physics';
import type { Truck } from './physics';

const INK = '#1a0d14';
type C = CanvasRenderingContext2D;

function poly(ctx: C, p: number[]) {
  ctx.beginPath();
  ctx.moveTo(p[0], p[1]);
  for (let i = 2; i < p.length; i += 2) ctx.lineTo(p[i], p[i + 1]);
  ctx.closePath();
}
function disc(ctx: C, x: number, y: number, r: number, color: string | CanvasGradient) {
  ctx.fillStyle = color;
  ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
}
function glow(ctx: C, r: number, color: string) {
  const g = ctx.createRadialGradient(0, 0, 0.1, 0, 0, r);
  g.addColorStop(0, color); g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.globalCompositeOperation = 'lighter';
  disc(ctx, 0, 0, r, g);
  ctx.globalCompositeOperation = 'source-over';
}

function wheel(ctx: C, x: number, y: number, ang: number) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(ang);
  disc(ctx, 0, 0, R, '#141318');
  ctx.fillStyle = '#26252d';
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * Math.PI * 2;
    ctx.save(); ctx.rotate(a); ctx.fillRect(R - 0.14, -0.1, 0.2, 0.2); ctx.restore();
  }
  ctx.strokeStyle = '#34333d'; ctx.lineWidth = 0.06;
  ctx.beginPath(); ctx.arc(0, 0, R * 0.72, 0, Math.PI * 2); ctx.stroke();
  const g = ctx.createRadialGradient(-0.12, 0.12, 0.02, 0, 0, R * 0.5);
  g.addColorStop(0, '#fff5b0'); g.addColorStop(0.6, '#ffc21a'); g.addColorStop(1, '#b97800');
  disc(ctx, 0, 0, R * 0.48, g);
  for (let i = 0; i < 5; i++) disc(ctx, Math.cos(i * 1.2566) * R * 0.3, Math.sin(i * 1.2566) * R * 0.3, 0.07, '#5b3a00');
  disc(ctx, 0, 0, 0.11, '#2a2a30');
  ctx.restore();
}

function spring(ctx: C, ax: number, ay: number, bx: number, by: number) {
  const dx = bx - ax, dy = by - ay, L = Math.hypot(dx, dy) || 1;
  const px = -dy / L, py = dx / L;
  ctx.strokeStyle = '#2b2b33'; ctx.lineWidth = 0.22;
  ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(bx, by); ctx.stroke();
  ctx.strokeStyle = '#3ee0ff'; ctx.lineWidth = 0.08;
  ctx.beginPath();
  for (let i = 0; i <= 7; i++) {
    const t = 0.12 + (i / 7) * 0.7, o = i % 2 ? 0.2 : -0.2;
    ctx.lineTo(ax + dx * t + px * o, ay + dy * t + py * o);
  }
  ctx.stroke();
}

export function drawTruck(ctx: C, tr: Truck, t: number, nitro: boolean, gas: number) {
  for (let i = 0; i < 2; i++) {
    const [ax, ay] = tr.local(ANCH_X[i], ANCH_Y);
    spring(ctx, ax, ay, tr.wheels[i].x, tr.wheels[i].y);
  }
  ctx.save();
  ctx.translate(tr.x, tr.y);
  ctx.rotate(tr.a);
  ctx.lineJoin = 'round';
  // Cono de luz del faro
  ctx.globalCompositeOperation = 'lighter';
  const lg = ctx.createRadialGradient(1.95, 0.3, 0.05, 1.95, 0.3, 4.5);
  lg.addColorStop(0, 'rgba(255,240,180,0.5)'); lg.addColorStop(1, 'rgba(255,200,120,0)');
  ctx.fillStyle = lg;
  poly(ctx, [1.95, 0.3, 6.5, 1.6, 6.5, -1.2]); ctx.fill();
  ctx.globalCompositeOperation = 'source-over';
  // Bastidor, parachoques y escape
  ctx.fillStyle = '#2a2a31'; ctx.fillRect(-1.7, -0.42, 3.4, 0.3);
  ctx.fillStyle = '#5c5c66'; ctx.fillRect(-1.95, -0.25, 0.3, 0.42); ctx.fillRect(1.75, -0.25, 0.3, 0.42);
  ctx.fillStyle = '#c9ccd6'; ctx.fillRect(-1.25, 0.5, 0.16, 0.95);
  ctx.fillStyle = '#7b7e88'; ctx.fillRect(-1.27, 1.38, 0.2, 0.1);
  // Carrocería
  const bg = ctx.createLinearGradient(0, 0.7, 0, -0.2);
  bg.addColorStop(0, '#ff7a3c'); bg.addColorStop(0.5, '#ff4a1c'); bg.addColorStop(1, '#a3200f');
  ctx.fillStyle = bg; ctx.strokeStyle = INK; ctx.lineWidth = 0.07;
  poly(ctx, [-1.85, -0.15, 1.85, -0.15, 1.98, 0.22, 1.7, 0.58, 1.0, 0.62, 0.62, 1.32, -0.55, 1.32, -0.78, 0.62, -1.8, 0.62, -1.95, 0.2]);
  ctx.fill(); ctx.stroke();
  // Ventana y piloto
  const wg = ctx.createLinearGradient(-0.5, 1.2, 0.7, 0.7);
  wg.addColorStop(0, '#9fe8ff'); wg.addColorStop(0.45, '#2c4f86'); wg.addColorStop(1, '#101a3a');
  ctx.fillStyle = wg;
  poly(ctx, [-0.6, 0.72, -0.44, 1.2, 0.5, 1.2, 0.82, 0.72]); ctx.fill();
  disc(ctx, 0.05, 0.92, 0.2, '#f4f4f8');
  ctx.fillStyle = '#ff2d55'; ctx.fillRect(-0.15, 0.95, 0.4, 0.07);
  ctx.fillStyle = 'rgba(255,255,255,0.35)';
  poly(ctx, [-0.3, 1.18, -0.1, 1.18, -0.38, 0.74, -0.55, 0.74]); ctx.fill();
  // Llamas decorativas
  const flame = (c: string, s: number) => {
    ctx.fillStyle = c;
    ctx.beginPath();
    ctx.moveTo(1.75 * s, 0.15 * s);
    ctx.bezierCurveTo(1.2 * s, 0.5 * s, 0.6 * s, 0.1 * s, 0.2 * s, 0.42 * s);
    ctx.bezierCurveTo(0, 0.2 * s, -0.4 * s, 0.35 * s, -0.6 * s, 0.15 * s);
    ctx.bezierCurveTo(-0.9 * s, 0.35 * s, -1.2 * s, 0.05 * s, -1.6 * s, 0.2 * s);
    ctx.bezierCurveTo(-1.2 * s, -0.1 * s, 0, 0.05 * s, 1.75 * s, 0);
    ctx.fill();
  };
  flame('#ffd23c', 1);
  flame('#ff9a1c', 0.6);
  // Barra de luces, faro y piloto trasero
  ctx.fillStyle = '#26262c'; ctx.fillRect(-0.5, 1.32, 1.05, 0.12);
  ctx.fillStyle = '#fff3b0';
  for (let i = 0; i < 4; i++) ctx.fillRect(-0.44 + i * 0.26, 1.44, 0.16, 0.1);
  disc(ctx, 1.88, 0.32, 0.11, '#fffbe0');
  ctx.fillStyle = '#ff2040'; ctx.fillRect(-1.97, 0.28, 0.12, 0.18);
  if (nitro) {
    ctx.globalCompositeOperation = 'lighter';
    const L = 1.6 + Math.sin(t * 60) * 0.3;
    const fg = ctx.createLinearGradient(-1.95, 0, -1.95 - L, 0);
    fg.addColorStop(0, 'rgba(180,240,255,1)'); fg.addColorStop(0.4, 'rgba(60,140,255,0.9)'); fg.addColorStop(1, 'rgba(60,80,255,0)');
    ctx.fillStyle = fg;
    poly(ctx, [-1.95, 0.3, -1.95 - L, 0.05, -1.95, -0.15]); ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
  } else if (gas > 0) disc(ctx, -1.17, 1.52, 0.07 + Math.random() * 0.06, 'rgba(255,170,60,0.8)');
  ctx.restore();
  for (const w of tr.wheels) wheel(ctx, w.x, w.y, w.ang);
}

/** Rampa metálica de salida con luces (el camión arranca saltando desde ella). */
export function drawStartRamp(ctx: C, x: number, y: number, t: number) {
  const g = ctx.createLinearGradient(0, y + 3.4, 0, y);
  g.addColorStop(0, '#6f6880'); g.addColorStop(1, '#2c2834');
  ctx.fillStyle = g; ctx.strokeStyle = INK; ctx.lineWidth = 0.1;
  poly(ctx, [x - 13, y - 0.3, x, y + 3.4, x + 0.3, y + 3.4, x + 0.3, y - 0.3]); ctx.fill(); ctx.stroke();
  ctx.strokeStyle = 'rgba(255,255,255,0.12)'; ctx.lineWidth = 0.12;
  ctx.beginPath();
  for (let i = 1; i < 6; i++) { const xx = x - 13 + i * 2.2; ctx.moveTo(xx, y - 0.3); ctx.lineTo(xx + 2.2, y - 0.3 + ((i + 1) * 2.2 * 3.7) / 13); }
  ctx.stroke();
  ctx.fillStyle = '#ffd23c'; ctx.fillRect(x - 0.1, y + 3.4, 0.4, 0.18);
  for (let i = 0; i < 7; i++) disc(ctx, x - 12.4 + i * 2, y - 0.18 + (0.6 + i * 2) * 0.2846, 0.13, Math.floor(t * 8) % 7 === i ? '#fff36a' : '#ff4a1c');
}

// ---------------- Objetos ----------------

export function drawCoin(ctx: C, x: number, y: number, t: number, big: boolean) {
  const r = big ? 0.5 : 0.36;
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(Math.abs(Math.cos(t * 3 + x * 0.5)) * 0.85 + 0.15, 1);
  const g = ctx.createRadialGradient(-r * 0.3, r * 0.3, 0.02, 0, 0, r);
  const c = big ? ['#ffe0ff', '#ff4fd8', '#8a1278'] : ['#fffbd0', '#ffcc1f', '#b8740a'];
  c.forEach((col, i) => g.addColorStop(i / 2, col));
  disc(ctx, 0, 0, r, g);
  ctx.strokeStyle = big ? '#ffd2f5' : '#fff1a0'; ctx.lineWidth = 0.05;
  ctx.beginPath(); ctx.arc(0, 0, r * 0.68, 0, Math.PI * 2); ctx.stroke();
  ctx.restore();
}

export function drawPower(ctx: C, kind: 'fuel' | 'nitro' | 'magnet', x: number, y: number, t: number) {
  ctx.save();
  ctx.translate(x, y + Math.sin(t * 3 + x) * 0.12);
  glow(ctx, 1.4, kind === 'fuel' ? 'rgba(255,90,60,0.5)' : kind === 'nitro' ? 'rgba(70,170,255,0.6)' : 'rgba(255,70,100,0.45)');
  ctx.strokeStyle = INK; ctx.lineWidth = 0.06;
  if (kind === 'fuel') {
    ctx.fillStyle = '#e8262c';
    poly(ctx, [-0.42, -0.55, 0.42, -0.55, 0.42, 0.35, 0.18, 0.55, -0.42, 0.55]); ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#ffd23c'; ctx.fillRect(-0.3, -0.1, 0.6, 0.18);
    ctx.fillStyle = '#333'; ctx.fillRect(0.2, 0.5, 0.16, 0.16);
  } else if (kind === 'nitro') {
    ctx.rotate(Math.sin(t * 2) * 0.15);
    ctx.fillStyle = '#1f6dff';
    ctx.beginPath(); ctx.roundRect(-0.28, -0.6, 0.56, 1.0, 0.2); ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#c9ccd6'; ctx.fillRect(-0.12, 0.4, 0.24, 0.22);
    ctx.fillStyle = '#9ff3ff';
    poly(ctx, [0.05, 0.28, -0.15, -0.05, 0.02, -0.05, -0.06, -0.42, 0.16, 0, 0, 0]); ctx.fill();
  } else {
    ctx.strokeStyle = '#e81f3a'; ctx.lineWidth = 0.28;
    ctx.beginPath(); ctx.moveTo(-0.38, 0.4); ctx.lineTo(-0.38, 0.05); ctx.arc(0, 0.05, 0.38, Math.PI, 0, true); ctx.lineTo(0.38, 0.4); ctx.stroke();
    ctx.fillStyle = '#e6e8ef'; ctx.fillRect(-0.52, 0.4, 0.28, 0.2); ctx.fillRect(0.24, 0.4, 0.28, 0.2);
  }
  ctx.restore();
}

export function drawCrate(ctx: C, x: number, y: number, s: number) {
  ctx.save();
  ctx.translate(x - s / 2, y);
  ctx.fillStyle = '#b8743a'; ctx.strokeStyle = '#4a2a12'; ctx.lineWidth = 0.08;
  ctx.fillRect(0, 0, s, s); ctx.strokeRect(0, 0, s, s); ctx.strokeRect(0.1, 0.1, s - 0.2, s - 0.2);
  ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(s, s); ctx.moveTo(s, 0); ctx.lineTo(0, s); ctx.stroke();
  ctx.restore();
}

export function drawBarrel(ctx: C, x: number, y: number, t: number) {
  ctx.save();
  ctx.translate(x, y);
  ctx.fillStyle = '#d62a2a'; ctx.strokeStyle = INK; ctx.lineWidth = 0.07;
  ctx.beginPath(); ctx.roundRect(-0.45, 0, 0.9, 1.25, 0.12); ctx.fill(); ctx.stroke();
  ctx.fillStyle = '#ffd23c'; ctx.fillRect(-0.45, 0.45, 0.9, 0.3);
  ctx.fillStyle = INK;
  for (let i = 0; i < 3; i++) { poly(ctx, [-0.4 + i * 0.3, 0.45, -0.25 + i * 0.3, 0.45, -0.35 + i * 0.3, 0.75, -0.5 + i * 0.3, 0.75]); ctx.fill(); }
  disc(ctx, 0, 1.32, 0.09, Math.sin(t * 8) > 0 ? '#ffef6a' : '#7a5a10');
  ctx.restore();
}

export function drawFlag(ctx: C, x: number, y: number, t: number, color: string) {
  ctx.fillStyle = '#e6e6ee';
  ctx.fillRect(x - 0.05, y, 0.1, 4);
  ctx.fillStyle = color;
  ctx.beginPath();
  for (let i = 0; i <= 6; i++) ctx.lineTo(x + 0.05 + i * 0.3, y + 4 - Math.sin(t * 5 + i) * 0.08);
  for (let i = 6; i >= 0; i--) ctx.lineTo(x + 0.05 + i * 0.3, y + 3.1 - Math.sin(t * 5 + i) * 0.08);
  ctx.fill();
}

// Terreno procedural: ruido de valor 1D + rampas "kicker" periódicas. Coordenadas en metros, y hacia arriba.
import type { Zone } from './types';

export function hash(n: number, seed: number) {
  const x = Math.sin(n * 127.1 + seed * 311.7) * 43758.5453;
  return x - Math.floor(x);
}

/** Ruido de valor suave en [-1, 1]. */
export function noise1(x: number, seed: number) {
  const i = Math.floor(x);
  const f = x - i;
  const u = f * f * (3 - 2 * f);
  return (hash(i, seed) * (1 - u) + hash(i + 1, seed) * u) * 2 - 1;
}

const smooth = (a: number, b: number, x: number) => {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
};

const RAMP_P = 135;
const RAMP_0 = 36;

export class Terrain {
  constructor(public zone: Zone, public seed: number) {}

  /** Altura del suelo en x. */
  h(x: number) {
    const z = this.zone;
    const s = this.seed;
    const k = smooth(14, 50, x);
    const grow = 1 + Math.min(1.5, Math.max(0, x) / 1300);
    let y = z.amp * grow * k * (
      noise1(x / 32, s) +
      noise1(x / 12.5, s + 7) * 0.3 * z.rough +
      noise1(x / 5, s + 13) * 0.06 * z.rough
    );
    y += noise1(x / 170, s + 3) * 16 * smooth(30, 120, x);
    if (z.id === 'luna') y -= this.crater(x);
    return y + this.ramp(x, grow);
  }

  slope(x: number) {
    return (this.h(x + 0.05) - this.h(x - 0.05)) / 0.1;
  }

  /** Rampas de salto: subida cóncava y caída suave tras el labio. */
  private ramp(x: number, grow: number) {
    const i0 = Math.floor((x - RAMP_0) / RAMP_P);
    let y = 0;
    for (let i = Math.max(0, i0 - 1); i <= i0 + 1; i++) {
      const p = RAMP_0 + i * RAMP_P + hash(i, this.seed + 5) * 45;
      const H = (2.4 + hash(i, this.seed + 9) * 1.8) * Math.min(1.6, grow);
      const L = 15;
      if (x > p - L && x <= p) { const t = (x - (p - L)) / L; y += H * t * t; }
      else if (x > p && x < p + 9) { const t = (x - p) / 9; y += H * (0.5 + 0.5 * Math.cos(Math.PI * t)); }
    }
    return y;
  }

  private crater(x: number) {
    const c = Math.floor(x / 48);
    if (c < 1 || hash(c, this.seed + 21) < 0.45) return 0;
    const cx = c * 48 + 24;
    const w = 6 + hash(c, this.seed + 22) * 5;
    const d = (x - cx) / w;
    if (Math.abs(d) > 1.3) return 0;
    return Math.abs(d) < 1 ? 1.9 * (1 - d * d) - 0.5 : -0.5 * (1 - (Math.abs(d) - 1) / 0.3);
  }

  /** Placas de hielo (zona nieve): menos agarre. */
  isIce(x: number) {
    if (this.zone.id !== 'nieve' || x < 60) return false;
    const c = Math.floor(x / 34);
    return hash(c, this.seed + 31) > 0.62 && x - c * 34 < 16;
  }

  gripAt(x: number) {
    return this.zone.grip * (this.isIce(x) ? 0.42 : 1);
  }
}

