export interface TruckParams { torque: number; omegaMax: number; k: number; c: number; mu: number; tank: number }

export function paramsFor(up: Record<UpgradeId, number>): TruckParams {
  return {
    torque: 34 + up.engine * 8,
    omegaMax: 26 + up.engine * 4,
    k: 430 + up.suspension * 70,
    c: 20 + up.suspension * 4,
    mu: 1.05 + up.tires * 0.15,
    tank: 34 + up.tank * 11,
  };
}

export interface Save { coins: number; up: Record<UpgradeId, number>; best: Record<ZoneId, number> }
const KEY = 'nona-monster-truck-v1';

export function loadSave(): Save {
  const base: Save = { coins: 0, up: { engine: 0, suspension: 0, tires: 0, tank: 0 }, best: { desierto: 0, nieve: 0, luna: 0 } };
  try {
    const s = JSON.parse(localStorage.getItem(KEY) || '{}') as Partial<Save>;
    return { coins: s.coins ?? 0, up: { ...base.up, ...(s.up || {}) }, best: { ...base.best, ...(s.best || {}) } };
  } catch { return base; }
}

export function writeSave(s: Save) {
  try { localStorage.setItem(KEY, JSON.stringify(s)); } catch { /* sin almacenamiento */ }
}

