// Objetos del mundo: monedas, combustible, nitro, imán, cajas y barriles explosivos. Generación por tramos.
import type { Terrain } from './terrain';
import type { Truck } from './physics';
import { drawBarrel, drawCoin, drawCrate, drawPower } from './sprites';

export type ItemKind = 'coin' | 'gem' | 'fuel' | 'nitro' | 'magnet' | 'crate' | 'barrel';
export interface Item { kind: ItemKind; x: number; y: number; alive: boolean; s: number }
export interface Hit { kind: ItemKind; x: number; y: number }

const CHUNK = 22;
const RADIUS: Record<ItemKind, number> = { coin: 1.5, gem: 1.6, fuel: 1.9, nitro: 1.9, magnet: 1.9, crate: 1.5, barrel: 1.4 };

export class World {
  items: Item[] = [];
  private genX = 0;
  private fuelNext = 0;
  private fuelGap = 0;
  private terr!: Terrain;

  reset(terr: Terrain, startX: number) {
    this.terr = terr;
    this.items = [];
    this.genX = startX + 8;
    this.fuelNext = startX + 105;
    this.fuelGap = 115;
    // Estela de monedas siguiendo el salto de salida
    const g = terr.zone.gravity, y0 = terr.h(startX) + 5.6;
    for (let i = 0; i < 8; i++) {
      const tt = (2.2 + i * 1.5) / 13;
      this.items.push({ kind: i === 4 ? 'gem' : 'coin', x: startX + 2.6 + i * 1.5, y: y0 + 5 * tt - (g / 2) * tt * tt, alive: true, s: 1 });
    }
  }

  private add(kind: ItemKind, x: number, lift: number, s = 1) {
    const y = kind === 'crate' || kind === 'barrel' ? this.terr.h(x) - 0.05 : this.terr.h(x) + lift;
    this.items.push({ kind, x, y, alive: true, s });
  }

  generate(toX: number) {
    for (; this.genX < toX; this.genX += CHUNK) this.chunk(this.genX);
  }

  private chunk(x0: number) {
    const dist = x0;
    if (x0 + CHUNK > this.fuelNext) {
      this.add('fuel', this.fuelNext, 1.6);
      this.fuelNext += this.fuelGap;
      this.fuelGap = Math.min(300, this.fuelGap + 16);
      return;
    }
    const r = Math.random();
    if (r < 0.5) {
      const n = 5 + Math.floor(Math.random() * 5);
      const gem = Math.random() < 0.14;
      const arc = Math.random() < 0.4;
      const sx = x0 + 2 + Math.random() * 5;
      for (let i = 0; i < n; i++) {
        const lift = 1.3 + (arc ? Math.sin((i / (n - 1)) * Math.PI) * 2.5 : 0);
        this.add(gem && i === Math.floor(n / 2) ? 'gem' : 'coin', sx + i * 1.5, lift);
      }
    } else if (r < 0.72) {
      const n = 1 + Math.floor(Math.random() * Math.min(3, 1 + dist / 400));
      const x = x0 + 8 + Math.random() * 8;
      for (let i = 0; i < n; i++) this.add('crate', x + i * 1.05, 0, 1);
      this.add('coin', x + n * 0.5, 2.6);
    } else if (r < 0.86 && dist > 60) {
      this.add('barrel', x0 + 10 + Math.random() * 8, 0);
    }
    const p = Math.random();
    if (p < 0.08) this.add('nitro', x0 + 17, 2.2);
    else if (p < 0.13) this.add('magnet', x0 + 17, 2.2);
  }

  /** Mueve monedas imantadas y devuelve las colisiones de este frame. */
  update(dt: number, tr: Truck, magnet: boolean): Hit[] {
    const hits: Hit[] = [];
    const pts: [number, number][] = [[tr.x, tr.y + 0.4], [tr.wheels[0].x, tr.wheels[0].y], [tr.wheels[1].x, tr.wheels[1].y], [...tr.local(1.6, 0.2)]];
    for (const it of this.items) {
      if (!it.alive) continue;
      if (magnet && (it.kind === 'coin' || it.kind === 'gem')) {
        const dx = tr.x - it.x, dy = tr.y - it.y, d = Math.hypot(dx, dy);
        if (d < 11) { const v = Math.min(d, (26 + (11 - d) * 3) * dt); it.x += (dx / d) * v; it.y += (dy / d) * v; }
      }
      const rad = RADIUS[it.kind];
      const cy = it.kind === 'crate' ? it.y + 0.5 : it.kind === 'barrel' ? it.y + 0.6 : it.y;
      for (const [px, py] of pts) {
        if (Math.abs(px - it.x) < rad && Math.abs(py - cy) < rad && Math.hypot(px - it.x, py - cy) < rad) {
          it.alive = false;
          hits.push({ kind: it.kind, x: it.x, y: cy });
          break;
        }
      }
    }
    this.items = this.items.filter(it => it.alive && it.x > tr.x - 45);
    return hits;
  }

  draw(ctx: CanvasRenderingContext2D, t: number, x0: number, x1: number) {
    for (const it of this.items) {
      if (it.x < x0 - 2 || it.x > x1 + 2) continue;
      switch (it.kind) {
        case 'coin': drawCoin(ctx, it.x, it.y, t, false); break;
        case 'gem': drawCoin(ctx, it.x, it.y, t, true); break;
        case 'fuel': case 'nitro': case 'magnet': drawPower(ctx, it.kind, it.x, it.y, t); break;
        case 'crate': drawCrate(ctx, it.x, it.y, it.s); break;
        case 'barrel': drawBarrel(ctx, it.x, it.y, t); break;
      }
    }
  }
}
